// Project-E — Stage 3A — Opportunity Scoring Engine v1.0.0
// n8n Code node
// Mode: Run Once for All Items
//
// PURPOSE
// Score only the opportunity itself.
//
// This node does NOT evaluate the freelancer.
// It does NOT calculate:
// - technology fit
// - problem fit
// - delivery confidence
// - portfolio alignment
// - capability gaps
// - apply / maybe / skip
//
// Personal fit will be calculated after Stage 3.5 retrieves
// and evaluates real portfolio evidence from Qdrant.

const items = $input.all();

if (items.length === 0) {
  throw new Error(
    "Calculate Opportunity Scores: no input received."
  );
}

if (items.length !== 1) {
  throw new Error(
    `Calculate Opportunity Scores: expected exactly 1 item, received ${items.length}.`
  );
}

const d = items[0].json ?? {};
const a = d.analysis_json ?? {};

const VERSION = "1.0.0";

// ============================================================
// Helpers
// ============================================================

function clamp(value) {
  return Math.max(
    0,
    Math.min(100, Math.round(Number(value) || 0))
  );
}

function text(value) {
  if (value === null || value === undefined) {
    return "";
  }

  if (Array.isArray(value)) {
    return value.map(text).join(" ");
  }

  if (typeof value === "object") {
    return Object.values(value).map(text).join(" ");
  }

  return String(value);
}

function normalize(value) {
  return text(value)
    .toLowerCase()
    .replace(/[–—]/g, "-")
    .replace(/\s+/g, " ")
    .trim();
}

function escapeRegExp(value) {
  return value.replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}

function containsPhrase(haystack, phrase) {
  const normalizedPhrase = normalize(phrase);

  if (!normalizedPhrase) {
    return false;
  }

  const pattern = escapeRegExp(normalizedPhrase)
    .replace(/\\ /g, "\\s+");

  return new RegExp(
    `(^|[^a-z0-9])${pattern}([^a-z0-9]|$)`,
    "i"
  ).test(haystack);
}

function hasAny(haystack, phrases) {
  return phrases.some(
    phrase => containsPhrase(haystack, phrase)
  );
}

function unique(values) {
  return [
    ...new Set(
      values.filter(
        value =>
          value !== null &&
          value !== undefined &&
          value !== ""
      )
    )
  ];
}

function isMissing(value) {
  return (
    value === null ||
    value === undefined ||
    value === ""
  );
}

function numberOrNull(value) {
  if (isMissing(value)) {
    return null;
  }

  const number = Number(value);

  return Number.isFinite(number)
    ? number
    : null;
}

function money(value) {
  if (isMissing(value)) {
    return null;
  }

  if (typeof value === "number") {
    return Number.isFinite(value)
      ? value
      : null;
  }

  const cleaned = String(value)
    .trim()
    .toUpperCase()
    .replace(/[€£$,\s]/g, "");

  const match = cleaned.match(
    /^(-?\d+(?:\.\d+)?)([KMB])?$/
  );

  if (!match) {
    return null;
  }

  const number = Number(match[1]);

  const multiplier = {
    K: 1e3,
    M: 1e6,
    B: 1e9
  }[match[2]] || 1;

  return Number.isFinite(number)
    ? number * multiplier
    : null;
}

function addAdjustment(
  collection,
  reason,
  points
) {
  collection.push({
    reason,
    points: Math.abs(points)
  });
}

function cleanStringArray(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  const output = [];
  const seen = new Set();

  for (const entry of value) {
    if (typeof entry !== "string") {
      continue;
    }

    const cleaned = entry.trim();

    if (!cleaned) {
      continue;
    }

    const key = cleaned.toLowerCase();

    if (!seen.has(key)) {
      seen.add(key);
      output.push(cleaned);
    }
  }

  return output;
}

// ============================================================
// Validate input
// ============================================================

const jobId = String(
  d.job_id ??
  a.job_id ??
  ""
).trim();

if (!jobId) {
  throw new Error(
    "Calculate Opportunity Scores: job_id is missing."
  );
}

if (
  !a ||
  typeof a !== "object" ||
  Array.isArray(a)
) {
  throw new Error(
    "Calculate Opportunity Scores: analysis_json is missing or invalid."
  );
}

// ============================================================
// Job-owned text
// ============================================================

const jobText = normalize([
  d.title,
  d.description,
  d.category,
  d.subcategory,
  d.skills,
  d.requirement_tools,
  d.requirement_languages,
  d.requirement_frameworks,
  d.requirement_models,
  d.requirement_databases,
  d.project_type
]);

const analysisText = normalize([
  a.job_understanding?.plain_english_summary,
  a.job_understanding?.core_problem,
  a.job_understanding?.likely_deliverable,
  a.job_understanding?.work_type,
  a.job_understanding?.job_family,
  a.classification?.primary_category,
  a.classification?.secondary_categories,
  a.classification?.automation_type,
  a.classification?.ai_level,
  a.classification?.business_domain
]);

const combinedWorkText = normalize([
  jobText,
  analysisText
]);

// ============================================================
// 1. Client Safety
// Higher score = safer/more attractive client profile
// ============================================================

function calculateClientSafety() {
  let score = 50;

  const bonuses = [];
  const penalties = [];
  const flags = [];
  const notes = [];
  const unknowns = [];

  const paymentVerified =
    d.client_payment_verified;

  const rating =
    numberOrNull(d.client_rating);

  const reviews =
    numberOrNull(d.client_reviews_count);

  const totalSpent =
    money(d.client_total_spent);

  const hires =
    numberOrNull(d.client_hires);

  const activeHires =
    numberOrNull(d.client_active_hires);

  const totalHours =
    numberOrNull(d.client_total_hours);

  if (paymentVerified === true) {
    score += 12;

    addAdjustment(
      bonuses,
      "Payment is verified",
      12
    );
  } else if (paymentVerified === false) {
    score -= 18;

    addAdjustment(
      penalties,
      "Payment is explicitly not verified",
      18
    );
  } else {
    unknowns.push(
      "payment_verification_unknown"
    );
  }

  if (rating === null) {
    unknowns.push(
      "client_rating_unknown"
    );
  } else if (rating >= 4.8) {
    score += 12;

    addAdjustment(
      bonuses,
      `Excellent client rating (${rating}/5)`,
      12
    );
  } else if (rating >= 4.5) {
    score += 7;

    addAdjustment(
      bonuses,
      `Good client rating (${rating}/5)`,
      7
    );
  } else if (rating < 3.5) {
    score -= 18;

    addAdjustment(
      penalties,
      `Poor client rating (${rating}/5)`,
      18
    );
  } else if (rating < 4.0) {
    score -= 8;

    addAdjustment(
      penalties,
      `Below-average client rating (${rating}/5)`,
      8
    );
  }

  if (reviews === null) {
    unknowns.push(
      "client_reviews_unknown"
    );
  } else if (reviews >= 20) {
    score += 5;

    addAdjustment(
      bonuses,
      "Substantial review history",
      5
    );
  }

  if (totalSpent === null) {
    unknowns.push(
      "client_spend_unknown"
    );
  } else if (totalSpent >= 100000) {
    score += 12;

    addAdjustment(
      bonuses,
      "Very substantial recorded client spend",
      12
    );
  } else if (totalSpent >= 10000) {
    score += 8;

    addAdjustment(
      bonuses,
      "Substantial recorded client spend",
      8
    );
  } else if (totalSpent >= 1000) {
    score += 4;

    addAdjustment(
      bonuses,
      "Established recorded client spend",
      4
    );
  } else if (totalSpent === 0) {
    notes.push(
      "No recorded client spend; treated neutrally as a possible new-client signal."
    );
  }

  if (hires === null) {
    unknowns.push(
      "client_hires_unknown"
    );
  } else if (hires >= 20) {
    score += 8;

    addAdjustment(
      bonuses,
      "Established hiring history",
      8
    );
  } else if (hires >= 1) {
    score += 4;

    addAdjustment(
      bonuses,
      "Some hiring history",
      4
    );
  }

  // A high number of hires with low spend can indicate
  // historically small engagement values.
  if (
    totalSpent !== null &&
    hires !== null &&
    hires >= 20
  ) {
    const spendPerHire =
      totalSpent / hires;

    if (spendPerHire < 25) {
      score -= 10;

      addAdjustment(
        penalties,
        "Recorded spending per hire is extremely low",
        10
      );

      flags.push(
        `Approximate recorded spend per hire is $${Math.round(spendPerHire)}.`
      );
    } else if (spendPerHire < 75) {
      score -= 5;

      addAdjustment(
        penalties,
        "Recorded spending per hire appears low",
        5
      );

      flags.push(
        `Approximate recorded spend per hire is $${Math.round(spendPerHire)}.`
      );
    }
  }

  if (
    hires !== null &&
    activeHires !== null &&
    hires > 0
  ) {
    const activeHireRatio =
      activeHires / hires;

    if (
      activeHires >= 20 &&
      activeHireRatio >= 0.25
    ) {
      flags.push(
        "Client has many active hires; engagement attention and management capacity may require review."
      );
    }
  }

  if (d.client_member_since) {
    notes.push(
      `Client member since ${d.client_member_since}.`
    );
  }

  const modelClientSignals =
    cleanStringArray(
      a.client_analysis
        ?.negative_client_signals
    );

  flags.push(...modelClientSignals);

  return {
    score: clamp(score),

    bonuses,
    penalties,
    flags: unique(flags),
    notes: unique(notes),
    unknowns: unique(unknowns),

    facts_used: {
      payment_verified:
        paymentVerified ?? null,

      rating,

      reviews_count:
        reviews,

      total_spent:
        totalSpent,

      hires,

      active_hires:
        activeHires,

      total_hours:
        totalHours
    },

    principle:
      "Client Safety uses observable client reliability and engagement-value facts. Unknown facts remain neutral, and competition is scored separately."
  };
}

// ============================================================
// 2. Estimate effort from job shape
//
// This is not personal delivery confidence.
// It estimates the apparent size of the advertised work.
// ============================================================

function detectEffortRange() {
  const explicitEffort = normalize(
    a.job_understanding
      ?.estimated_effort
  );

  const explicitRange =
    explicitEffort.match(
      /(\d+(?:\.\d+)?)\s*(?:-|to)\s*(\d+(?:\.\d+)?)\s*hours?/
    );

  if (explicitRange) {
    return {
      min: Number(explicitRange[1]),
      max: Number(explicitRange[2]),
      source: "stage_2_explicit_range"
    };
  }

  const explicitSingle =
    explicitEffort.match(
      /(\d+(?:\.\d+)?)\s*hours?/
    );

  if (explicitSingle) {
    const hours =
      Number(explicitSingle[1]);

    return {
      min: Math.max(
        1,
        Math.round(hours * 0.75)
      ),

      max: Math.max(
        1,
        Math.round(hours * 1.5)
      ),

      source:
        "stage_2_single_estimate"
    };
  }

  let range = {
    min: 6,
    max: 16,
    source:
      "general_project_heuristic"
  };

  if (
    hasAny(
      combinedWorkText,
      [
        "desktop application",
        "desktop app",
        "desktop gui",
        "executable",
        "installer"
      ]
    )
  ) {
    range = {
      min: 16,
      max: 40,
      source:
        "desktop_application_heuristic"
    };
  } else if (
    hasAny(
      combinedWorkText,
      [
        "full-stack",
        "full stack",
        "web application",
        "frontend and backend"
      ]
    )
  ) {
    range = {
      min: 24,
      max: 60,
      source:
        "full_stack_heuristic"
    };
  } else if (
    hasAny(
      combinedWorkText,
      [
        "rag",
        "retrieval augmented",
        "vector database",
        "embeddings",
        "ai agent",
        "multi-agent"
      ]
    )
  ) {
    range = {
      min: 12,
      max: 36,
      source:
        "ai_system_heuristic"
    };
  } else if (
    hasAny(
      combinedWorkText,
      [
        "business automation",
        "workflow automation",
        "automate repetitive",
        "business process automation",
        "crm automation"
      ]
    )
  ) {
    range = {
      min: 6,
      max: 24,
      source:
        "automation_heuristic"
    };
  } else if (
    hasAny(
      combinedWorkText,
      [
        "debug",
        "fix bug",
        "troubleshoot",
        "broken workflow",
        "repair existing"
      ]
    )
  ) {
    range = {
      min: 2,
      max: 12,
      source:
        "debugging_heuristic"
    };
  }

  const complexity = normalize(
    a.job_understanding
      ?.complexity_level
  );

  const scopeSize = normalize(
    a.job_understanding
      ?.scope_size
  );

  if (
    hasAny(
      complexity,
      ["high", "very high"]
    )
  ) {
    range = {
      ...range,
      min: range.min * 1.4,
      max: range.max * 1.6
    };
  } else if (
    hasAny(
      complexity,
      ["low", "very low"]
    )
  ) {
    range = {
      ...range,
      min: range.min * 0.7,
      max: range.max * 0.75
    };
  }

  if (
    hasAny(
      scopeSize,
      ["large", "very large"]
    )
  ) {
    range = {
      ...range,
      min: range.min * 1.3,
      max: range.max * 1.5
    };
  } else if (
    hasAny(
      scopeSize,
      ["very small"]
    )
  ) {
    range = {
      ...range,
      min: range.min * 0.6,
      max: range.max * 0.65
    };
  }

  return {
    min: Math.max(
      1,
      Math.round(range.min)
    ),

    max: Math.max(
      1,
      Math.round(range.max)
    ),

    source:
      range.source
  };
}

// ============================================================
// 3. Budget Fit
// Higher score = healthier commercial value
// ============================================================

function calculateBudgetFit() {
  let score = 50;

  const bonuses = [];
  const penalties = [];
  const flags = [];
  const notes = [];

  const fixedPrice =
    money(d.fixed_price);

  const hourlyMin =
    money(d.hourly_min);

  const hourlyMax =
    money(d.hourly_max);

  const effortRange =
    detectEffortRange();

  const explicitFullTime =
    hasAny(
      jobText,
      [
        "full-time",
        "full time",
        "40 hours per week",
        "40 hours",
        "5 days a week",
        "every working day"
      ]
    );

  const fixedFullTimeMismatch =
    d.job_type === "fixed" &&
    explicitFullTime;

  let effectiveHourlyRange = null;

  if (fixedFullTimeMismatch) {
    score -= 30;

    addAdjustment(
      penalties,
      "A fixed budget is explicitly paired with a full-time schedule",
      30
    );

    flags.push(
      "Fixed-price/full-time mismatch."
    );
  } else if (
    d.job_type === "fixed" &&
    fixedPrice !== null
  ) {
    effectiveHourlyRange = {
      conservative:
        Math.round(
          (fixedPrice / effortRange.max) *
          100
        ) / 100,

      optimistic:
        Math.round(
          (fixedPrice / effortRange.min) *
          100
        ) / 100
    };

    const averageHours =
      (
        effortRange.min +
        effortRange.max
      ) / 2;

    const midpointRate =
      fixedPrice / averageHours;

    if (midpointRate >= 50) {
      score += 30;

      addAdjustment(
        bonuses,
        "Strong estimated commercial value",
        30
      );
    } else if (midpointRate >= 25) {
      score += 18;

      addAdjustment(
        bonuses,
        "Good estimated commercial value",
        18
      );
    } else if (midpointRate >= 15) {
      score += 5;

      addAdjustment(
        bonuses,
        "Potentially acceptable commercial value",
        5
      );
    } else if (midpointRate >= 8) {
      score -= 15;

      addAdjustment(
        penalties,
        "Likely low effective value for the requested scope",
        15
      );
    } else {
      score -= 28;

      addAdjustment(
        penalties,
        "Likely very low effective value for the requested scope",
        28
      );
    }
  } else if (
    d.job_type === "hourly" &&
    (
      hourlyMin !== null ||
      hourlyMax !== null
    )
  ) {
    const representativeRate =
      hourlyMax ?? hourlyMin;

    if (representativeRate >= 40) {
      score += 20;

      addAdjustment(
        bonuses,
        "Strong advertised hourly rate",
        20
      );
    } else if (
      representativeRate >= 25
    ) {
      score += 10;

      addAdjustment(
        bonuses,
        "Reasonable advertised hourly rate",
        10
      );
    } else if (
      representativeRate < 10
    ) {
      score -= 20;

      addAdjustment(
        penalties,
        "Very low advertised hourly rate",
        20
      );
    }
  } else {
    flags.push(
      "Budget could not be evaluated reliably."
    );
  }

  if (
    d.contract_to_hire === true ||
    d.long_term === true
  ) {
    notes.push(
      "Future work potential does not compensate for weak value in the current advertised engagement."
    );
  }

  const modelBudgetRisks =
    cleanStringArray(
      a.job_risk_analysis
        ?.budget_risks
    );

  flags.push(...modelBudgetRisks);

  return {
    score: clamp(score),

    fixed_price:
      fixedPrice,

    hourly_min:
      hourlyMin,

    hourly_max:
      hourlyMax,

    estimated_effort_range_hours:
      effortRange,

    estimated_effective_hourly_range:
      effectiveHourlyRange,

    explicit_full_time_fixed_price_mismatch:
      fixedFullTimeMismatch,

    bonuses,
    penalties,
    flags: unique(flags),
    notes: unique(notes),

    principle:
      "Budget Fit evaluates the advertised commercial value using job shape and scope. It does not consider the freelancer's capability or speed."
  };
}

// ============================================================
// 4. Competition Fit
// Higher score = easier opportunity
// ============================================================

function calculateCompetitionFit() {
  let score = 50;

  const bonuses = [];
  const penalties = [];
  const flags = [];

  const proposals =
    normalize(d.proposals);

  const interviewing =
    numberOrNull(d.interviewing);

  const invites =
    numberOrNull(d.invites_sent);

  const posted =
    normalize(d.posted_time);

  const lastViewed =
    normalize(
      d.last_viewed_by_client
    );

  if (
    hasAny(
      proposals,
      ["less than 5"]
    )
  ) {
    score += 35;

    addAdjustment(
      bonuses,
      "Very low proposal count",
      35
    );
  } else if (
    hasAny(
      proposals,
      ["5 to 10"]
    )
  ) {
    score += 25;

    addAdjustment(
      bonuses,
      "Low proposal count",
      25
    );
  } else if (
    hasAny(
      proposals,
      ["10 to 15"]
    )
  ) {
    score += 10;

    addAdjustment(
      bonuses,
      "Moderate proposal count",
      10
    );
  } else if (
    hasAny(
      proposals,
      ["15 to 20"]
    )
  ) {
    score -= 5;

    addAdjustment(
      penalties,
      "Some competition",
      5
    );
  } else if (
    hasAny(
      proposals,
      ["20 to 50"]
    )
  ) {
    score -= 20;

    addAdjustment(
      penalties,
      "High proposal count",
      20
    );
  } else if (
    containsPhrase(
      proposals,
      "50+"
    ) ||
    containsPhrase(
      proposals,
      "50 or more"
    )
  ) {
    score -= 35;

    addAdjustment(
      penalties,
      "Very high proposal count",
      35
    );
  } else if (!proposals) {
    flags.push(
      "Proposal count unknown."
    );
  }

  if (
    interviewing !== null &&
    interviewing >= 3
  ) {
    score -= 25;

    addAdjustment(
      penalties,
      "Client is already interviewing several freelancers",
      25
    );
  } else if (
    interviewing !== null &&
    interviewing >= 1
  ) {
    score -= 10;

    addAdjustment(
      penalties,
      "Client is already interviewing",
      10
    );
  }

  if (
    invites !== null &&
    invites >= 5
  ) {
    score -= 15;

    addAdjustment(
      penalties,
      "Client sent several invitations",
      15
    );
  } else if (
    invites !== null &&
    invites >= 1
  ) {
    score -= 5;

    addAdjustment(
      penalties,
      "Client sent invitations",
      5
    );
  }

  if (
    /\b(minutes?|hours?)\s+ago\b/
      .test(posted)
  ) {
    score += 15;

    addAdjustment(
      bonuses,
      "Recently posted",
      15
    );
  }

  if (
    hasAny(
      lastViewed,
      [
        "2 weeks ago",
        "3 weeks ago",
        "4 weeks ago",
        "1 month ago",
        "2 months ago"
      ]
    )
  ) {
    score -= 10;

    addAdjustment(
      penalties,
      "Client has not viewed the job recently",
      10
    );
  }

  return {
    score: clamp(score),

    proposals:
      d.proposals ?? null,

    interviewing,

    invites_sent:
      invites,

    posted_time:
      d.posted_time ?? null,

    last_viewed_by_client:
      d.last_viewed_by_client ?? null,

    bonuses,
    penalties,
    flags,

    principle:
      "Competition Fit evaluates application timing and marketplace activity only. It does not assess the client or freelancer."
  };
}

// ============================================================
// 5. Project Safety
// Higher score = clearer and safer delivery opportunity
// ============================================================

function calculateProjectSafety() {
  let score = 75;

  const bonuses = [];
  const penalties = [];
  const flags = [];

  const explicitAmbiguity =
    hasAny(
      jobText,
      [
        "not sure what we need",
        "don't know what we need",
        "scope not defined",
        "requirements not defined",
        "details to be discussed",
        "open-ended project"
      ]
    );

  const specificationSignals = [
    "you'll deliver",
    "you will deliver",
    "deliverables",
    "requirements file",
    "expected output",
    "must have",
    "acceptance criteria",
    "success criteria",
    "working code",
    "documentation",
    "sop"
  ].filter(
    phrase =>
      containsPhrase(jobText, phrase)
  );

  if (explicitAmbiguity) {
    score -= 20;

    addAdjustment(
      penalties,
      "Scope is explicitly undefined",
      20
    );
  }

  if (
    specificationSignals.length >= 2
  ) {
    score += 10;

    addAdjustment(
      bonuses,
      "Multiple concrete delivery requirements are present",
      10
    );
  }

  if (
    hasAny(
      jobText,
      [
        "unlimited revisions",
        "other tasks as assigned",
        "anything else required",
        "ongoing changes",
        "additional features as needed"
      ]
    )
  ) {
    score -= 12;

    addAdjustment(
      penalties,
      "Open-ended work creates scope-creep risk",
      12
    );
  }

  if (
    hasAny(
      jobText,
      [
        "legacy code",
        "undocumented system",
        "no documentation",
        "reverse engineer",
        "take over from another freelancer"
      ]
    )
  ) {
    score -= 15;

    addAdjustment(
      penalties,
      "Inherited or undocumented system risk",
      15
    );
  }

  if (
    hasAny(
      jobText,
      [
        "urgent",
        "asap",
        "immediately",
        "today",
        "same day",
        "within 2 hours"
      ]
    )
  ) {
    score -= 20;

    addAdjustment(
      penalties,
      "High deadline pressure",
      20
    );
  }

  const scopeRisks =
    cleanStringArray(
      a.job_risk_analysis
        ?.scope_risks
    );

  const technicalRisks =
    cleanStringArray(
      a.job_risk_analysis
        ?.technical_risks
    );

  const redFlags =
    cleanStringArray(
      a.job_risk_analysis
        ?.red_flags
    );

  const missingInformation =
    cleanStringArray(
      a.quality_control
        ?.missing_information
    );

  const targetedUnknowns = [];

  const combinedRiskText =
    normalize([
      scopeRisks,
      technicalRisks,
      missingInformation
    ]);

  if (
    hasAny(
      combinedRiskText,
      [
        "platform",
        "operating system",
        "os target"
      ]
    )
  ) {
    targetedUnknowns.push(
      "target platform"
    );
  }

  if (
    hasAny(
      combinedRiskText,
      [
        "packaging",
        "installation",
        "installer"
      ]
    )
  ) {
    targetedUnknowns.push(
      "packaging or installation expectations"
    );
  }

  if (
    hasAny(
      combinedRiskText,
      [
        "maintenance",
        "support expectations",
        "ongoing support"
      ]
    )
  ) {
    targetedUnknowns.push(
      "maintenance expectations"
    );
  }

  if (
    hasAny(
      combinedRiskText,
      [
        "deliverable",
        "milestone",
        "scope boundary",
        "scope unclear"
      ]
    )
  ) {
    targetedUnknowns.push(
      "deliverable boundaries"
    );
  }

  if (
    hasAny(
      combinedRiskText,
      [
        "access",
        "credentials",
        "permissions"
      ]
    )
  ) {
    targetedUnknowns.push(
      "access dependencies"
    );
  }

  const uniqueUnknowns =
    unique(targetedUnknowns);

  if (uniqueUnknowns.length > 0) {
    const points = Math.min(
      uniqueUnknowns.length * 3,
      12
    );

    score -= points;

    addAdjustment(
      penalties,
      "Specific delivery details remain unresolved",
      points
    );
  }

  flags.push(
    ...redFlags,
    ...scopeRisks,
    ...technicalRisks
  );

  if (
    a.quality_control
      ?.should_be_reviewed_manually === true
  ) {
    flags.push(
      "Manual review recommended by Stage 2."
    );
  }

  if (
    a.job_understanding
      ?.is_expired_or_unavailable === true
  ) {
    score = 0;

    flags.push(
      "Job is expired or unavailable."
    );
  }

  return {
    score: clamp(score),

    bonuses,
    penalties,
    flags: unique(flags),

    unresolved_scope_details:
      uniqueUnknowns,

    specification_signals:
      specificationSignals,

    principle:
      "Project Safety evaluates clarity, scope control, deadline pressure and delivery risk. It does not assess personal ability."
  };
}

